    public Map<String, Object> parseWsTrade(Map<String, Object> trade, Map<String, Object> market)
    {
        //
        //     {
        //         "buy_order_id": 1211625836466176,
        //         "amount_str": "1.08000000",
        //         "timestamp": "1584642064",
        //         "microtimestamp": "1584642064685000",
        //         "id": 108637852,
        //         "amount": 1.08,
        //         "sell_order_id": 1211625840754689,
        //         "price_str": "6294.77",
        //         "type": 1,
        //         "price": 6294.77
        //     }
        //
        Long microtimestamp = this.safeInteger(trade, "microtimestamp", 0);
        String id = this.safeString(trade, "id");
        Long timestamp = this.parseToInt((((double) microtimestamp) / ((double) 1000)));
        String price = this.safeString(trade, "price");
        String amount = this.safeString(trade, "amount");
        Map<String, Object> marketResolved = this.safeMarket((String) null, market, (String) null, (String) null);
        String symbol = (String) marketResolved.get("symbol");
        Long sideRaw = this.safeInteger(trade, "type");
        String side = "sell";
        if ((sideRaw != null && sideRaw == 0))
        {
            side = "buy";
        }
        return (Map<String, Object>) (this.safeTrade(Helpers.newMap(
            "info", trade,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "symbol", symbol,
            "id", id,
            "order", null,
            "type", null,
            "takerOrMaker", null,
            "side", side,
            "price", price,
            "amount", amount,
            "cost", null,
            "fee", null
        ), marketResolved));
    }

    public void handleTrade(Client client, Map<String, Object> message)
    {
        //
        //     {
        //         "data": {
        //             "buy_order_id": 1207733769326592,
        //             "amount_str": "0.14406384",
        //             "timestamp": "1583691851",
        //             "microtimestamp": "1583691851934000",
        //             "id": 106833903,
        //             "amount": 0.14406384,
        //             "sell_order_id": 1207733765476352,
        //             "price_str": "8302.92",
        //             "type": 0,
        //             "price": 8302.92
        //         },
        //         "event": "trade",
        //         "channel": "live_trades_btcusd"
        //     }
        //
        // the trade streams push raw trade information in real-time
        // each trade has a unique buyer and seller
        String channel = this.safeString(message, "channel");
        if (java.util.Objects.equals(channel, null))
        {
            return;
        }
        List<Object> parts = new ArrayList<Object>(Arrays.asList(((String)channel).split(java.util.regex.Pattern.quote("_"))));
        String marketId = this.safeString(parts, 2);
        Map<String, Object> market = this.safeMarket(marketId, (Map<String, Object>) null, (String) null, (String) null);
        String symbol = (String) market.get("symbol");
        String messageHash = ("trades:" + symbol);
        Map<String, Object> data = (Map<String, Object>) this.safeDict(message, "data", (Object) null);
        Map<String, Object> trade = this.parseWsTrade((Map<String, Object>) (data), market);
        io.github.ccxt.ws.ArrayCache tradesArray = (io.github.ccxt.ws.ArrayCache) this.safeValue(this.trades, symbol);
        if (java.util.Objects.equals(tradesArray, null))
        {
            Long limit = this.safeInteger(this.options, "tradesLimit", 1000);
            tradesArray = new ArrayCache(((Number)limit).intValue());
            Helpers.addElementToObject(this.trades, symbol, tradesArray);
        }
        tradesArray.append(trade);
        client.resolve(tradesArray, messageHash);
    }

